def link_existing_college_records(apps, schema_editor):
    College = apps.get_model('notices', 'College')
    Notice = apps.get_model('notices', 'Notice')
    StudentProfile = apps.get_model('notices', 'StudentProfile')
    database = schema_editor.connection.alias

    default_college, _ = College.objects.using(database).get_or_create(
        name=DEFAULT_COLLEGE_NAME,
        defaults={'code': None},
    )
    profiles = StudentProfile.objects.using(database).filter(
        college__isnull=True,
    )
    for profile in profiles.iterator():
        college, _ = College.objects.using(database).get_or_create(
            name=profile.college_name,
            defaults={'code': None},
        )
        StudentProfile.objects.using(database).filter(pk=profile.pk).update(
            college_id=college.pk,
        )

    Notice.objects.using(database).filter(college__isnull=True).update(
        college_id=default_college.pk,
    )


